grant create on schema api,app_private,finance_private to git_tutor_commands;
create function app_private.post_tutor_source_award(p_kind text,p_occurrence_id uuid,p_decision_id uuid,p_amount_minor bigint,p_reason text,p_expected_version integer,p_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;o app_private.occurrences%rowtype;source uuid;tutor uuid;assignment uuid;fee uuid;amount bigint;effective timestamptz;earning uuid:=gen_random_uuid();ledger uuid;begin
 perform app_private.require_role(actor,'admin');select * into o from app_private.occurrences where id=p_occurrence_id for update;if o.id is null then raise exception'NOT_FOUND';end if;
 if p_kind='cancellation_award'then select b.id,b.tutor_id,b.amount_minor,b.created_at into source,tutor,amount,effective from finance_private.cancellation_compensation_obligations b where b.proposal_id=p_decision_id and b.occurrence_id=o.id;
  if source is null then raise exception'NOT_FOUND';end if;if o.state<>'cancelled'or o.tutor_id<>tutor then raise exception'STATE_CONFLICT';end if;select a.id into assignment from app_private.tutor_assignments a where a.occurrence_id=o.id and a.tutor_id=tutor order by a.version desc limit 1;fee:=o.current_fee_agreement_id;
 elsif p_kind='reassignment_award'then select b.id,b.tutor_id,b.amount_minor,b.created_at,b.original_assignment_id,b.base_fee_agreement_id into source,tutor,amount,effective,assignment,fee from finance_private.tutor_reassignment_obligations b join app_private.tutor_reassignments r on r.id=b.proposal_id where b.proposal_id=p_decision_id and b.occurrence_id=o.id and r.state='committed';if source is null then raise exception'NOT_FOUND';end if;
 else raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,'approve_'||p_kind,jsonb_build_object('occurrence_id',p_occurrence_id,'decision_id',p_decision_id,'amount_minor',p_amount_minor,'reason',p_reason,'expected_version',p_expected_version),p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if exists(select 1 from finance_private.tutor_earnings where source_type=p_kind and source_id=source)then raise exception'STATE_CONFLICT';end if;if o.version is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;
 if amount is distinct from p_amount_minor or p_reason is null or length(btrim(p_reason))not between 1 and 2000 or assignment is null then raise exception'VALIDATION_ERROR';end if;
 ledger:=finance_private.finance_post_balanced('tutor-award:'||source,p_kind,source,'EGP',effective,case when amount=0 then'[]'::jsonb else jsonb_build_array(jsonb_build_object('account_code','tutor_expense','signed_minor',amount),jsonb_build_object('account_code','tutor_payable','signed_minor',-amount))end,ctx);
 insert into finance_private.tutor_earnings(id,tutor_id,occurrence_id,assignment_id,fee_agreement_id,source_type,source_id,amount_minor,ledger_transaction_id,effective_at,command_id)values(earning,tutor,o.id,assignment,fee,p_kind,source,amount,ledger,effective,(ctx->>'command_id')::uuid);
 return app_private.booking_finish(ctx,o.id,o.version,jsonb_build_object('earning_id',earning,'amount_minor',amount),'tutor_earning_posted',jsonb_build_object('earning_id',earning,'tutor_id',tutor,'occurrence_id',o.id));end$$;
create function api.approve_cancellation_award(p_occurrence_id uuid,p_cancellation_decision_id uuid,p_amount_minor bigint,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.post_tutor_source_award('cancellation_award',p_occurrence_id,p_cancellation_decision_id,p_amount_minor,p_reason,p_expected_version,p_idempotency_key)$$;
create function api.approve_reassignment_award(p_occurrence_id uuid,p_reassignment_id uuid,p_amount_minor bigint,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path='' as $$select app_private.post_tutor_source_award('reassignment_award',p_occurrence_id,p_reassignment_id,p_amount_minor,p_reason,p_expected_version,p_idempotency_key)$$;
create function api.list_tutor_awards(p_tutor_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();teacher uuid;items jsonb;begin
 if app_private.has_role(actor,'admin')then teacher:=p_tutor_id;else perform app_private.require_role(actor,'tutor');select id into teacher from app_private.tutors where account_id=actor;if teacher is null or(p_tutor_id is not null and teacher<>p_tutor_id)then raise exception'FORBIDDEN';end if;end if;if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 with sources as(select id,proposal_id,occurrence_id,tutor_id,amount_minor,'cancellation_award'::text kind from finance_private.cancellation_compensation_obligations union all select id,proposal_id,occurrence_id,tutor_id,amount_minor,'reassignment_award'from finance_private.tutor_reassignment_obligations)
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select b.id,jsonb_build_object('award_id',b.id,'occurrence_id',b.occurrence_id,'tutor_id',b.tutor_id,'source_type',b.kind,'cancellation_decision_id',case when b.kind='cancellation_award'then b.proposal_id end,'reassignment_id',case when b.kind='reassignment_award'then b.proposal_id end,'amount_minor',b.amount_minor,'earning_id',e.id,'version',o.version,'can_post',e.id is null and app_private.has_role(actor,'admin'))item from sources b join app_private.occurrences o on o.id=b.occurrence_id left join finance_private.tutor_earnings e on e.source_type=b.kind and e.source_id=b.id where(teacher is null or b.tutor_id=teacher)and(p_cursor is null or b.id>p_cursor)order by b.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'award_id'else null end);end$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.proname=any(array['post_tutor_source_award','approve_cancellation_award','approve_reassignment_award','list_tutor_awards'])and n.nspname in('api','app_private')loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
